def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=grid[0][1]
    border=next(v for v in set(sum(grid,[])) if v!=bg and sum(row.count(v) for row in grid for _ in [0])>=0 and sum(x==v for row in grid for x in row)>1)
    marker=next(v for v in set(sum(grid,[])) if v not in (bg,border))
    out=[r[:] for r in grid]
    for i in range(h):
      for j in range(w):
        if grid[i][j]==marker:
          # draw straight line from marked cell to closest border edge; color line in marker
          edges=[]
          for y in range(h):
            if grid[y][j]==border: edges.append((abs(y-i),y,j))
          for x in range(w):
            if grid[i][x]==border: edges.append((abs(x-j),i,x))
          if edges:
            _,ei,ej=min(edges)
            di=0 if ei==i else (1 if ei>i else -1)
            dj=0 if ej==j else (1 if ej>j else -1)
            y,x=i,j
            while (y,x)!=(ei,ej):
              out[y][x]=marker; y+=di; x+=dj
    return out
