def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Find the background, frame color, and ray color.
    from collections import Counter
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    frame=max((v for v in cnt if v!=bg),key=lambda v:cnt[v])
    ray=next(v for v in cnt if v not in (bg,frame))
    # For each straight frame segment, cast perpendicular rays from alternate
    # interior cells (one cell inward from the endpoint, then every other cell).
    for col in range(w):
        inds=[i for i in range(h) if grid[i][col]==frame]
        if len(inds)>1 and inds==list(range(min(inds),max(inds)+1)):
            for i in range(min(inds)+1,max(inds)+1,2):
                for j in range(w):
                    if grid[i][j]==bg: out[i][j]=ray
    for row in range(h):
        inds=[j for j,v in enumerate(grid[row]) if v==frame]
        if len(inds)>1 and inds==list(range(min(inds),max(inds)+1)):
            for j in range(min(inds)+1,max(inds)+1,2):
                for i in range(h):
                    if grid[i][j]==bg: out[i][j]=ray
    for i in range(h):
        for j in range(w):
            if grid[i][j]==ray: out[i][j]=4
    return out
